#include<bits/stdc++.h>
using namespace std;
int main(){
	int n; scanf("%d",&n);
	for(int i=n;i>=0;i--){
		int a; scanf("%d",&a);
		if(!a)continue; 
		if(a>0&&i!=n)putchar('+'); 
		if(a<0)putchar('-');

		if(abs(a)!=1||!i)printf("%d",abs(a)); 

		if(i){ 
			putchar('x');
			if(i!=1)printf("^%d",i);
		}
	}
	return 0;
}
